import csv, collections, math
runs=list(csv.DictReader(open('/app/data/mes_log.csv')))
tc=list(csv.DictReader(open('/app/data/thermocouples.csv')))
by=collections.defaultdict(list)
for r in tc: by[(r['run_id'],r['tc_id'],r['tc_location'])].append((float(r['time_s']),float(r['temp_c'])))
def ramp(vals):
    vals=sorted(vals); best=None
    for (t0,y0),(t1,y1) in zip(vals,vals[1:]):
        if t1>t0 and 100<=y0<=150 and 100<=y1<=150:
            s=(y1-y0)/(t1-t0)
            if s>0 and (best is None or s>best): best=s
    return best
def tal(vals,thr):
    vals=sorted(vals); total=0
    for (t0,y0),(t1,y1) in zip(vals,vals[1:]):
        if t1<=t0: continue
        if y0>thr and y1>thr: total+=t1-t0
        elif (y0<=thr<y1 or y1<=thr<y0) and y1!=y0:
            cross=t0+(thr-y0)*(t1-t0)/(y1-y0)
            total += t1-cross if y0<=thr<y1 else cross-t0
    return total
locs={k[1]:k[2] for k in by if k[0]=='R0001'}
print('locations',locs)
for run in sorted({r['run_id'] for r in runs}):
    liquidus=float(next(r['solder_liquidus_c'] for r in runs if r['run_id']==run))
    vals=[]
    for (rid,tid,loc),x in by.items():
        if rid==run: vals.append((tid,loc,ramp(x),tal(x,liquidus),max(y for t,y in x)))
    vals.sort()
    maxr=max((x for x in vals if x[2] is not None),key=lambda x:(x[2],-int(x[0][2:])))
    minTal=min(vals,key=lambda x:x[3]); maxTal=max(vals,key=lambda x:x[3]); minPeak=min(vals,key=lambda x:x[4])
    print(run,'maxr',maxr[:3],'large/small',[(x[0],x[2]) for x in vals[:2]],'tal min/max',minTal[:4],maxTal[:4],'peak min',minPeak[0:5:2])
